const corsUrl="https://cors.weboasis.workers.dev/corsproxy/?apiurl=",selectedUrl="https://duckduckgo.com/ac/?q=",searchTerm=searchInput.placeholder;let AutoComp=[];async function fetchAutoComp(a){AutoComp=[];try{let b=await fetch(corsUrl+selectedUrl+a);let c=await b.json();c.forEach(a=>{AutoComp.push(a.phrase)})}catch(e){console.log("Autocomplete suggestions unavailable:",e)}selectedIndex=-1,buildHelp()}function handleSearchReset2(){buildHelp()}